'use strict';
let countries=[],days=[],points=[],experiences=[],lodgings=[],currentCountry='finland',view={type:'home'},maps=[],observer=null,expanded=null,expandedPoints=[],navLock=false,lastFocus=null,keepNavOnRoute=false,budgetReturnState=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allText=n=>'t'in n?[n.t]:(n.c||[]).flatMap(allText);
const countryOf=d=>countries.find(c=>c.days.includes(d));
const countryById=id=>countries.find(c=>c.id===id)||countries[0];
const tagHTML=tags=>`<div class="tagline">${tags.map(t=>`<span class="tag ${t.includes('✈')?'flight':''}">${esc(t)}</span>`).join('')}</div>`;
const photoSrc=(src,width=480)=>{const match=src.match(/^(.*assets\/)(day-\d{2}-[0-2])\.jpg$/);return match?`${match[1]}optimized/${match[2]}-${width}.jpg`:src;};
const photoSizes='(max-width: 860px) 30vw, (max-width: 1470px) 22vw, 330px';
const photoHTML=(photos,compact=false,priority=false)=>photos.length?`<div class="photo-strip ${compact?'compact':''}">${photos.map((p,i)=>`<figure class="photo"><img src="${photoSrc(p.src)}" srcset="${p.srcset?p.srcset:p.thumb?`${p.thumb} 240w, ${p.src} 960w`:`${photoSrc(p.src,480)} 480w, ${photoSrc(p.src,640)} 640w, ${photoSrc(p.src,960)} 960w`}" sizes="${photoSizes}" width="960" height="540" alt="${esc(p.label)}" loading="${priority&&i<3?'eager':'lazy'}" fetchpriority="${priority&&i===0?'high':'auto'}" decoding="async"><figcaption>${esc(p.label)}</figcaption></figure>`).join('')}</div>`:'';
let placeAliases=[],placePattern=null;
const mapsURL=query=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query);
function buildPlaceLinks(){const cities=new Set(['Helsinki Finland','Rovaniemi Finland','Tromso Norway','Reykjavik Iceland','Copenhagen Denmark','Shanghai China','Milan Italy']);const aliases=new Map(),add=(label,query)=>{if(!cities.has(query)&&label&&(label.length>1||label==='Å')&&!aliases.has(label))aliases.set(label,query);};for(const c of countries)for(const p of c.mapAliases||[])add(p.label,p.query);for(const p of points){const name=p.name.replace(/（.*?）/g,'');add(name,p.query);const latin=name.match(/^([\p{Script=Latin}\d .’'／·()-]+?)\s+(?=[\u3400-\u9fff])/u);if(latin)add(latin[1].trim(),p.query);const chinese=name.match(/([\u3400-\u9fff][\u3400-\u9fff\s]*)$/);if(chinese&&chinese[1].trim().length>2&&!/^(海滩|观景台|渔村|购物街|地铁站|集合点|住宿区域|徒步起点|冰川徒步区域|峡湾|主街|百货|黄色渔屋|红色渔屋|桥梁)$/.test(chinese[1]))add(chinese[1].trim(),p.query);}
const extra={'p1':['中央车站'],'p3':['大教堂外观'],'p4':['港口街区','赫尔辛基 · 南港'],'p5':['Esplanadi'],'p6':['Marimekko'],'p8':['Stockmann'],'p10':['Liberty or Death'],'p11':['老市场'],'p12':['Design District'],'p14':['岩石教堂','Temppeliaukio Church'],'p16':['树怪森林','Riisitunturi 森林公园'],'p18':['Apukka','Apukka 私人湖畔桑拿与冰浴'],'p19':['圣诞老人集市'],'p21':['Ersfjordbotn'],'p23':['Storgata'],'p25':['Radisson Blu'],'p26':['Kvaløya','鲸岛'],'p30':['Mefjordvær'],'p40':['斯沃尔维尔'],'p42':['亨宁斯维尔'],'p44':['雷纳'],'p49':['Å'],'p51':['凯夫拉维克机场（KEF）','凯夫拉维克机场'],'p52':['雷克雅未克'],'p55':['Seljalandsfoss'],'p56':['斯科加瀑布'],'p58':['维克','Vík'],'p63':['斯卡夫塔山'],'p65':['Hof 村','Hof'],'p68':['冰河湖'],'p69':['钻石沙滩'],'p71':['Blue Lagoon','蓝湖'],'p74':['阿美琳堡宫','Amalienborg','Amalienborg Palace'],'p77':['丹麦设计博物馆','Designmuseum Danmark'],'p78':['Strøget'],'p79':['路易斯安那现代艺术博物馆','Louisiana','Louisiana Museum of Modern Art'],'p80':['Torvehallerne','TorvehallerneKBH'],'p81':['Rosenborg'],'p83':['Nørrebro','Nørrebro／Jægersborggade'],'p84':['Vesterbro','Vesterbro／Istedgade']};for(const [id,labels] of Object.entries(extra)){const p=points.find(x=>x.id===id);if(p)labels.forEach(label=>add(label,p.query));}
for(const [label,query] of Object.entries({'赫尔辛基':'Helsinki Finland','罗瓦涅米':'Rovaniemi Finland','特罗姆瑟':'Tromso Norway','塞尼亚岛':'Senja Norway','塞尼亚':'Senja Norway','罗弗敦群岛':'Lofoten Norway','罗弗敦岛':'Lofoten Norway','罗弗敦':'Lofoten Norway','哥本哈根':'Copenhagen Denmark','上海':'Shanghai China','米兰':'Milan Italy','Pohjoisesplanadi':'Pohjoisesplanadi Helsinki','Aleksanterinkatu 50':'Aleksanterinkatu 50 Helsinki','Aleksanterinkatu 52':'Aleksanterinkatu 52 Helsinki','Fredrikinkatu':'Fredrikinkatu Helsinki','Erottaja':'Erottaja Helsinki','Keramiker Inge Vincents':'Keramiker Inge Vincents Copenhagen','Ladyfingers':'Ladyfingers Copenhagen','Coffee Collective':'Coffee Collective Jaegersborggade Copenhagen','Kyoto':'Kyoto Istedgade 95 Copenhagen','Víkurkirkja 维克教堂外观':'Vikurkirkja Vik Iceland','Kirkjubæjarklaustur 教堂镇':'Kirkjubaejarklaustur Iceland'}))add(label,query);
placeAliases=[...aliases].sort((a,b)=>b[0].length-a[0].length);placePattern=new RegExp(placeAliases.map(([label])=>label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gu');}
function placeText(text,links=[]){if(!placePattern)return esc(text);const lookup=new Map(placeAliases),pattern=new RegExp(placePattern.source,'gu');let html='',last=0;for(const match of text.matchAll(pattern)){const label=match[0],i=match.index,before=text[i-1]||'',after=text[i+label.length]||'';if((/[\p{Script=Latin}\d]/u.test(label[0])&&/[\p{Script=Latin}\d]/u.test(before))||(/[\p{Script=Latin}\d]/u.test(label.at(-1))&&/[\p{Script=Latin}\d]/u.test(after)))continue;html+=esc(text.slice(last,i))+`<a class="place-link" href="${esc(mapsURL(lookup.get(label)))}" target="_blank" rel="noopener" aria-label="在 Google Maps 中打开${esc(label)}">${esc(label)}</a>`;last=i+label.length;}return html+esc(text.slice(last));}
function inlineText(text,links=[],emphasize=false){const colon=text.indexOf('：');if(emphasize&&colon>=0&&colon<75)return `<strong>${placeText(text.slice(0,colon+1),links)}</strong>${placeText(text.slice(colon+1),links)}`;return placeText(text,links);}
function textHTML(node){return node.t.split('\n').map(line=>`<span class="text-line">${inlineText(line,node.links||[],true)}</span>`).join('');}
function renderCopy(n){if(!n.t||/官网\s*[／/]\s*详情/.test(n.t))return '';const lines=n.t.split('\n').filter(Boolean);if(lines.length>1)return `<ul class="copy copy-list">${lines.map(line=>`<li>${inlineText(line,n.links||[],true)}</li>`).join('')}</ul>`;return `<p class="copy">${textHTML(n)}</p>`;}
function renderInfo(n){const paragraph=(n.c||[]).find(x=>x.name==='Paragraph');let main=paragraph?.c||n.c||[];if(main.length===1&&main[0].name==='Frame 55')main=main[0].c||[];const flight=main.some(x=>'t'in x&&/航空/.test(x.t))||(main.length>=3&&main.some(x=>'t'in x&&/\d[:：]\d/.test(x.t))&&main.some(x=>'t'in x&&/[¥￥€]/.test(x.t)));const cell=t=>`<span class="${/[¥￥€]/.test(t)?'price':/\d[:：]\d|分钟|营业|全程/.test(t)?'schedule':''}">${placeText(t).replace(/\n/g,'<br>')}</span>`;const row=main.map((x,i)=>{if('t'in x)return `<span class="info-cell ${/[¥￥€]/.test(x.t)?'price':i===0?'info-label':flight||/\d[:：]\d|分钟|全程|营业/.test(x.t)?'schedule':''}">${placeText(x.t)}</span>`;return `<span class="info-end">${allText(x).map(cell).join('')}</span>`;}).join('');const details=(n.c||[]).filter(x=>x!==paragraph);return `<div class="info-box ${flight?'flight-box':''}"><div class="info-row">${row}</div>${paragraph?details.map(x=>'t'in x?`<p class="info-detail">${inlineText(x.t,x.links||[])}</p>`:renderNode(x)).join(''):''}</div>`;}
function renderNode(n){if('t'in n)return renderCopy(n);const list=allText(n).filter(Boolean);if(!list.length)return '';if(/拍照点/.test(n.name))return `<div class="photo-note"><span class="note-label">📸 拍照点</span><span>${placeText(list.filter(t=>!['📸','拍照点'].includes(t)).join(' '))}</span></div>`;if(/交通胶囊|时长胶囊|活动时长标签|chip|badge/i.test(n.name))return `<div class="pill-box">${list.map(t=>`<p class="copy"><span class="text-line">${placeText(t).replace(/\n/g,'<br>')}</span></p>`).join('')}</div>`;if(n.name==='Background'||n.name==='价格与时长卡')return renderInfo(n);if((n.c||[]).some(x=>/交通胶囊|活动时长标签/.test(x.name||'')))return `<div class="activity-tags">${n.c.map(renderNode).join('')}</div>`;return `<div>${(n.c||[]).map(renderNode).join('')}</div>`;}

function destinationLink(p){return `<a class="place-link" href="${esc(mapsURL(p.query))}" target="_blank" rel="noopener" aria-label="在 Google Maps 中打开${esc(p.label)}">${esc(p.label)}</a>`;}

const isActivityInfoNode=n=>n.name==='Background'||n.name==='价格与时长卡';
function activityInfoHTML(a){const card=a.infoCard;if(!card||card.type!=='experience')return '';let price=esc(card.price);if(card.price==='stay'){const stay=lodgings.find(s=>s.id===card.stayId);price=stay?`住宿 ${stayPrice(stay)}／人／${stay.nights}晚`:'住宿价格待确认';}return `<div class="info-box activity-info-card"><div class="info-row"><span class="info-cell schedule">${esc(card.time)}</span><span class="info-cell price">${price}</span></div>${card.note?`<p class="info-detail">${esc(card.note)}</p>`:''}</div>`;}

function activityNavigationHTML(a){return a.navigation?.description?renderCopy({t:a.navigation.description}):'';}
const driveLabel=name=>({'Super central studio apartment':'市中心公寓','EIRA Fjord Stay':'EIRA民宿','Zero Car取还车点':'Zero Car','Hesten徒步起点':'Hesten起点','The Chess House':'Fredvang民宿','Lofoten Rorbuer':'Lofoten Rorbuer'})[name]||name;
function activityDrivesHTML(a){if(!a.drives?.length)return '';return `<div class="drive-tags" aria-label="自驾路段">${a.drives.map(d=>{const url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(d.origin)+'&destination='+encodeURIComponent(d.destination)+'&travelmode=driving'+(d.waypoints?.length?'&waypoints='+encodeURIComponent(d.waypoints.join('|')):'');return `<a class="drive-tag" href="${esc(url)}" target="_blank" rel="noopener" aria-label="查看${esc(d.from)}到${esc(d.to)}的自驾路线" title="公里数与车程为规划估算，冬季按当天导航和路况调整">🚗 ${esc(driveLabel(d.from))} → ${esc(driveLabel(d.to))} · 约${esc(d.distance)} · ${esc(d.duration)}</a>`;}).join('')}</div>`;}

const flightLabel=(d,t)=>t.includes('✈')?t+({1:'，12:55抵达',2:'，08:35抵达',9:'，14:20抵达',14:'，11:45抵达',15:'，次日13:30抵达'}[d.num]||''):t;
const daylightByDay={"1": {"date": "2027-02-06", "location": "赫尔辛基", "sunrise": "08:25", "sunset": "16:45"}, "2": {"date": "2027-02-07", "location": "特罗姆瑟", "sunrise": "08:55", "sunset": "15:00"}, "9": {"date": "2027-02-14", "location": "雷克雅未克", "sunrise": "09:25", "sunset": "18:00"}, "14": {"date": "2027-02-19", "location": "哥本哈根", "sunrise": "07:25", "sunset": "17:20"}};
const referenceRates={finland:'1 EUR ≈ 7.5 RMB',norway:'1 NOK ≈ 0.7 RMB',iceland:'100 ISK ≈ 5.5 RMB',denmark:'1 DKK ≈ 1 RMB'};
function countryReferenceHTML(c){const light=daylightByDay[c.days[0].num];if(!light)return '';return `<div class="country-reference" aria-label="${esc(c.name)}日照与汇率参考"><div class="country-reference-row"><span title="${esc(light.date+' · '+light.location+' · 当地时间参考')}">日出/日落：${light.sunrise} - ${light.sunset}</span><a class="country-rate" href="https://www.ecb.europa.eu/stats/exchange/eurofxref/shared/pdf/2026/11/20261103.pdf" target="_blank" rel="noopener" title="2026-11-03 欧洲央行参考汇率取近似值，非实时汇率">${esc(referenceRates[c.id])}</a></div></div>`;}
function rememberBudgetPosition(href){if(view.type!=='budget')return;budgetReturnState={top:window.scrollY||0,excludedOpen:!!$('.budget-excluded')?.open,href};}
function restoreBudgetPosition(state){const excluded=$('.budget-excluded');if(excluded)excluded.open=state.excludedOpen;const link=state.href?document.querySelector(`.budget-project[href="${state.href}"]`):null;link?.focus({preventScroll:true});const restore=()=>{if(view.type==='budget'&&budgetReturnState===state)window.scrollTo({top:state.top,behavior:'instant'});};restore();if(typeof requestAnimationFrame==='function')requestAnimationFrame(restore);}
if(window.history&&'scrollRestoration' in window.history)window.history.scrollRestoration='manual';
function mediaDay(d,c,home=false){const meta=home?`<p class="overview-meta">${[d.tags.filter(t=>!t.includes('✈')).join(' · ')||'无自驾'].map(t=>`<span class="driving-text">${esc(t)}</span>`).join('')}${d.tags.filter(t=>t.includes('✈')).map(t=>`<span class="flight-text">${esc(flightLabel(d,t))}</span>`).join('')}</p>`:tagHTML(d.tags.map(t=>flightLabel(d,t)));return `<a class="media-day ${home?'home-day':!d.photos.length?'no-photos':''}" href="#day/${d.num}" style="--theme:${c.color}">${home?`<div class="side-thumb home-thumb">${dayThumbnail(d)?`<img src="${dayThumbnail(d)}" width="160" height="90" alt="" loading="lazy" decoding="async">`:''}<span>D${d.num}</span></div>`:`<span class="day-num">${String(d.num).padStart(2,'0')}</span>`}<div><h3>${esc(d.title)}</h3><p class="date">${esc(d.date)}</p>${meta}</div>${home?'':photoHTML(d.photos,true)}</a>`;}
function dayRanges(dayNumbers){const sorted=[...new Set(dayNumbers)].sort((a,b)=>a-b),groups=[];for(const day of sorted){const last=groups.at(-1);if(last&&day===last[1]+1)last[1]=day;else groups.push([day,day]);}return groups.map(([first,last])=>first===last?`D${first}`:`D${first}–D${last}`).join(' · ');}
function cityMapLabel(p){return p.core?`<span class="city-label-name">${esc(p.name)}</span><span class="city-label-days">${esc(dayRanges(p.days))}</span>`:esc(p.name);}
const cityProfiles={"p24": {"intro": "特罗姆瑟把北极户外体验与城市生活连在一起：白天可以前往周边岛屿和峡湾，返回后仍能在港口、博物馆、餐厅与咖啡馆里放松。", "plan": "D2（2月7日）鲸岛自驾与缆车；D3上午自主滑雪、下午驯鹿；D4峡湾游船与海钓后去塞尼亚；D8返回，D9飞冰岛。", "highlights": ["鲸岛Kvaløya：Ersfjordbotn峡湾短途自驾。", "海上峡湾游船、驯鹿雪橇或越野滑雪入门。", "城市散步：极地博物馆、Storgata与港口。"], "source": "https://www.visittromso.no/winter"}, "p30": {"intro": "塞尼亚常被称为“微缩挪威”：陡峭山体、峡湾、白沙海滩与渔业村落交替出现，风景主要沿海岸公路展开，适合边开边停。", "plan": "D4晚上抵达并连住北部两晚；D5（2月10日）Hesten徒步看Segla，D6上午海岸短停后直接赴罗弗敦南部Fredvang。", "highlights": ["Hesten：冬季向导带队，从观景路线欣赏Segla。", "Ersfjordstranda：海滩与环抱海湾的山体。", "Tungeneset、Bergsbotn：本行程中的海岸与峡湾观景停留。", "Mefjordvær一带：渔村、山海景色与住宿安排。"], "source": "https://www.visittromso.no/region/senja"}, "p40": {"intro": "罗弗敦群岛最鲜明的画面，是雪山直接落入海面，桥梁串起渔村、海湾和白沙滩。冬季的渔业生活也是旅行的一部分，港口、渔船与红色渔屋让风景更有生活感。", "plan": "D6（2月11日）塞尼亚直接到Fredvang入住；D7游览南部后住斯沃尔维尔，D8游览北部后返回特罗姆瑟。", "highlights": ["斯沃尔维尔：港口生活与渔村散步。", "亨宁斯维尔：桥梁相连的海岛渔村和港湾街道。", "Hamnøy、雷纳：红色渔屋、桥梁、雪峰与海湾。"], "source": "https://www.nasjonaleturistveger.no/en/routes/lofoten"}, "p52": {"intro": "雷克雅未克是冰岛首都，紧凑的市中心适合步行。哈尔格林姆教堂、海边的Harpa音乐厅，与街头的咖啡馆和商店形成建筑、海港与城市生活相连的游览节奏。", "plan": "D9（2月14日）14:20抵达机场，取车后约16:30–17:00在哈尔格林姆斯教堂拍秋千与外观，再去Hveragerði的INNI精品公寓；D10出发南岸；D13返程，D14（2月19日）飞哥本哈根。", "highlights": ["城市地标：哈尔格林姆教堂与Harpa音乐厅。", "海滨与街头：港口方向散步、沿途咖啡与购物。", "南岸自驾：此处是出发和返程的城市枢纽。"], "source": "https://www.visiticeland.com/the-regions/reykjavik-the-capital/"}, "p58": {"intro": "维克是冰岛南岸的小型海滨村落，周边由黑沙、玄武岩、海蚀柱与山体构成强烈的地貌对比。这里也是本行程瀑布段与冰川段之间的休整点。", "plan": "D10看双瀑布后住维克，D11看黑沙滩，再经教堂镇东行至Hof。", "highlights": ["Reynisfjara：黑沙滩、玄武岩柱与离岸海蚀柱。", "镇内短走：海滨村落与周围山海景色。", "行程补给：结合原计划在镇内用餐、加油后继续东行。"], "source": "https://www.south.is/en/destinations/towns/vik"}, "p65": {"intro": "Hof村附近是本次南岸行程的冰川腹地住宿区域。与城市街区不同，这一段的重点是草皮教堂、山体、冰川地貌，以及前往冰洞和冰河湖的衔接。", "plan": "D11抵达霍芬附近，D12上午冰河湖与钻石沙滩、11:00起参加冰川团，D13向西返程。", "highlights": ["Hofskirkja：原行程中可顺路短停的草皮教堂。", "Jökulsárlón：Ice Walkers Tours冰川徒步与偏远冰洞的集合点。", "Jökulsárlón与钻石沙滩：D12冰川与海岸拍摄安排。"], "source": "https://www.visiticeland.com/the-regions/the-south/"}, "p73": {"intro": "哥本哈根把港口风景、丹麦设计与城市日常放在很近的距离内。新港的彩色建筑、设计博物馆、家居店和步行街，适合在旅程最后几天放慢节奏。", "plan": "D14（2月19日）新港、王宫教堂外观与FRAMA；D15设计博物馆、Illums Bolighus、黑钻图书馆，20:00飞上海。", "highlights": ["新港、阿美琳堡宫与腓特列教堂外观。", "FRAMA、Illums Bolighus与丹麦设计博物馆。", "黑钻图书馆：临水现代建筑和公共中庭。"], "source": "https://www.visitcopenhagen.com/copenhagen/planning/inspiration/72-hours-in-copenhagen"}, "p1": {"intro": "赫尔辛基适合把公共建筑、历史街区与芬兰设计放进一条步行路线：中央车站、Oodi、岩石教堂，以及Esplanadi周边商店各有不同的建筑与生活气质。", "plan": "D1（2月6日）下午看赫尔辛基公共建筑与设计商店；D2乘07:35–08:35航班抵达特罗姆瑟。", "highlights": ["Oodi：木质曲面与公共阅读空间。", "岩石教堂：避开周日礼拜，按当周观光时间取舍。", "Esplanadi、Marimekko与Stockmann：择店逛芬兰设计。"], "source": "https://oodihelsinki.fi/en/"}};
cityProfiles["p-reystays"]={"intro": "霍芬是冰岛东南海岸的小镇，也是本次连住两晚的住宿基地。周边可看雪山、冰川与海岸，Stokksnes蝙蝠山位于镇东。", "plan": "D11抵达REY Stays；D12清晨西行到Hof参加冰洞，下午冰河湖后回住处；D13蝙蝠山后西返。", "highlights": ["REY Stays：两卧室、窗景及露台。", "冰河湖与钻石沙滩位于西侧，冰洞当天需往返。", "Stokksnes：山峰、黑沙丘和海岸摄影。"], "source": "https://www.booking.com/hotel/is/reystays-lodges.zh-cn.html"};
function coreCities(){const specs=[["p1", "赫尔辛基", "Helsinki Finland", null, [1, 2], "right", [9, 8]], ["p24", "特罗姆瑟", "Tromso Norway", null, [2, 3, 4, 8, 9], "right", [9, -24]], ["p30", "塞尼亚", "Senja Norway", null, [4, 5, 6], "left", [-9, 0]], ["p40", "罗弗敦群岛", "Lofoten Norway", null, [6, 7, 8], "left", [-9, 24]], ["p52", "雷克雅未克", "Reykjavik Iceland", null, [9, 10, 13, 14], "top", [0, -12]], ["p58", "维克", "Vik Iceland", null, [10, 11], "bottom", [0, 9]], ["p-reystays", "霍芬 Höfn", "Hofn Iceland", null, [11, 12, 13], "right", [9, 0]], ["p73", "哥本哈根", "Copenhagen Denmark", null, [14, 15], "right", [9, 0]]];return specs.map(([id,name,query,coord,ds,direction,offset])=>{const original=points.find(p=>p.id===id),profile=cityProfiles[id];return {...original,cityProfile:profile,id:'core-'+id,name,query,coord:coord||original.coord,days:ds,core:true,kind:'city',direction,offset,description:profile.intro,imageReference:true};});}

function sideRender(){const c=countryById(currentCountry);$('#side-tabs').innerHTML=countries.map(x=>`<button data-side-country="${x.id}" style="--theme:${x.color}" class="${c.id===x.id?'active':''}" aria-selected="${c.id===x.id}">${x.name}</button>`).join('');$('#side-content').innerHTML=`<div class="side-guide-links" style="--theme:${c.color}"><a class="side-guide-card ${['attractions','attraction','country-intro'].includes(view.type)?'active':''}" href="#attractions/${c.id}">经典景点</a><a class="side-guide-card ${['restaurants','restaurant'].includes(view.type)?'active':''}" href="#restaurants/${c.id}">餐厅／酒吧</a></div><div class="side-label">DAILY ITINERARY / 每日行程</div>${c.days.map(d=>`<a href="#day/${d.num}" class="side-day ${view.num===d.num?'active':''}" style="--theme:${c.color}"><div class="side-thumb">${dayThumbnail(d)?`<img src="${dayThumbnail(d)}" width="160" height="90" alt="" loading="lazy" fetchpriority="low" decoding="async">`:''}<span>DAY ${String(d.num).padStart(2,'0')}</span></div><div><h3>${esc(d.title)}</h3><small>${esc(d.date.split(' · ')[0])}</small></div></a>`).join('')}`;document.documentElement.style.setProperty('--accent',c.color);$$('.budget-icon,.mobile-budget').forEach(el=>{el.classList.toggle('active',['budget','experience','stay'].includes(view.type));if(['budget','experience','stay'].includes(view.type))el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
function setCountry(id){currentCountry=id;sideRender();$$('[data-home-country]').forEach(b=>{const a=b.dataset.homeCountry===id;b.classList.toggle('active',a);b.setAttribute('aria-selected',String(a));});}
function mapMarkup(id,title,pts){return `<div class="map-block"><div class="map-canvas" id="${id}" aria-label="${esc(title)}"></div><div class="map-banner"><strong>${esc(title)}</strong><div class="map-banner-meta"><span>${pts.length} 个${pts[0]?.core?'核心城市／区域':'行程点位'} · 点击标记探索</span>${id==='country-map'?'<span class="map-route-legend">虚线：自驾／飞行／轮渡</span>':''}</div></div><button class="expand-map" data-expand="${id}" aria-label="展开地图与点位列表"><svg class="map-control-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" focusable="false"><path d="M14 3h7v7M21 3l-7 7M10 21H3v-7M3 21l7-7"/></svg></button></div>`;}
function getPoints(type,id){if(type==='home')return coreCities();if(type==='country'){const c=countryById(id);return points.filter(p=>p.coord&&p.countryId===c.id&&p.days.some(n=>c.days.some(d=>d.num===n)));}const excluded={9:['p0','p20'],14:['p51']};const ordered=countryDayStops[Number(id)]||[];return points.filter(p=>p.coord&&p.days.includes(Number(id))&&!(excluded[Number(id)]||[]).includes(p.id)).sort((a,b)=>{const ai=ordered.indexOf(a.id),bi=ordered.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);});}
function staySummaryTable(){const rows=[["2.6", "浦东✈️赫尔辛基", "约11h15m", ["2.6 上海 08:40 → 赫尔辛基 12:55 · 直飞 ¥6,141"]], ["2.7", "赫尔辛基✈️特罗姆瑟", "2h", ["2.7 赫尔辛基 07:35 → 特罗姆瑟 08:35 · 直飞 ¥2,265"]], ["2.7–2.14", "挪威北部", "—", []], ["2.14–2.19", "冰岛南岸", "7h30m（含转机）", ["2.14 特罗姆瑟 07:50 → 雷克雅未克 14:20 / 卑尔根中转2h50m · ¥1,487"]], ["2.19–2.20", "哥本哈根", "直飞3h15m", ["2.19 雷克雅未克 07:30 → 哥本哈根 11:45 · 直飞 ¥1,692"]], ["2.20–2.21", "哥本哈根✈️上海", "10h30m", ["2.20 哥本哈根 20:00 → 上海 次日13:30 · 直飞 ¥4,376"]]];return `<section class="stay-summary" aria-label="日期、地点与飞行时长"><div class="stay-table-scroll" role="region" aria-label="横向滚动完整行程表格" tabindex="0"><table><thead><tr><th scope="col">日期</th><th scope="col">地点</th><th scope="col"><span class="stay-flight-heading">飞行时长</span></th></tr></thead><tbody>${rows.map(([date,place,duration,details])=>`<tr class="stay-main-row"><td>${esc(date)}</td><td>${esc(place)}</td><td class="stay-flight-cell"><span>${esc(duration)}</span>${details.length?`<small class="stay-flight-options" tabindex="0" title="${esc(details.join(' / '))}">${esc(details.join(' / '))}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section><p class="holiday-note">春节假期：2.5-2.13<span class="flight-local-time">航班时刻均为当地时间</span></p>`;}

function renderHome(){const pts=getPoints('home');$('#main').innerHTML=`<div class="page-wrap"><header class="home-intro"><div><span class="eyebrow">NORDIC JOURNEY / 2027 · VERSION 2</span><h1>北欧<span>旅行计划</span><small class="version-badge">V2</small></h1></div><div class="intro-meta"><strong>4 个国家 · 16 天</strong><br>2027.02.06 — 02.21</div></header>${mapMarkup('home-map','四国路线总览',pts)}<p class="version-difference">相比 V1，V2 取消罗瓦涅米，2月7日08:35抵达特罗姆瑟；增加一天塞尼亚，冰岛顺延一天，哥本哈根压缩为两天，仍2月21日抵沪。</p>${staySummaryTable()}<nav class="country-tabs" aria-label="国家电梯导航">${countries.map(c=>`<button data-home-country="${c.id}" style="--theme:${c.color}" aria-selected="false">${c.name}</button>`).join('')}</nav>${countries.map(c=>`<section class="country-card home-country-card" aria-label="${c.name}行程" id="section-${c.id}" data-country-section="${c.id}" style="--theme:${c.color}">${countryReferenceHTML(c)}${c.days.map(d=>mediaDay(d,c,true)).join('')}</section>`).join('')}</div>`;createMap('home-map',pts,'四国路线总览');setCountry(currentCountry);observer=new IntersectionObserver(entries=>{if(navLock)return;const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible[0])setCountry(visible[0].target.dataset.countrySection);},{rootMargin:'-130px 0px -55% 0px',threshold:0});$$('[data-country-section]').forEach(n=>observer.observe(n));}
function renderCountry(c){const pts=getPoints('country',c.id);$('#main').innerHTML=`<div class="page-wrap" style="--theme:${c.color}"><header class="country-cover"><span class="eyebrow">NORDIC JOURNEY / 2027 · VERSION 2</span><h1>${esc(c.cover[1])}<span>${c.subtitle}</span></h1></header>${mapMarkup('country-map',c.name+'路线总览',pts)}<section class="country-card">${countryReferenceHTML(c)}${c.days.map(d=>mediaDay(d,c,true)).join('')}</section>${c.notes.map(t=>`<p class="source-note">${esc(t)}</p>`).join('')}</div>`;createMap('country-map',pts,c.name+'路线总览',false,c.id);}
function renderDay(d,c){const pts=getPoints('day',d.num),prev=days.find(x=>x.num===d.num-1),next=days.find(x=>x.num===d.num+1);$('#main').innerHTML=`<div class="page-wrap" style="--theme:${c.color}"><nav class="breadcrumb"><a href="#home">首页</a><span>/</span><a href="#country/${c.id}">${c.name}</a><span>/ DAY ${String(d.num).padStart(2,'0')}</span></nav><article class="detail-card"><header class="day-heading day-heading-flow"><span class="day-num">${String(d.num).padStart(2,'0')}</span><div class="heading-info"><h1>${placeText(d.title)}</h1><p>${esc(d.date)}</p>${d.tags.filter(t=>!t.includes('✈')).length?`<p class="day-drive-meta">${d.tags.filter(t=>!t.includes('✈')).map(esc).join(' · ')}</p>`:''}${d.activities.some(a=>a.drives?.length)?'<p class="drive-estimate-note">里程按2026.11.10导航参考；冬季车程留有缓冲，点击标签查看路线。</p>':''}${d.tags.some(t=>t.includes('✈'))?`<p class="day-flight-meta">${d.tags.filter(t=>t.includes('✈')).map(t=>esc(flightLabel(d,t))).join('<br>')}</p>`:''}</div></header>${dayPhotos(d).length?`<div class="detail-photos">${photoHTML(dayPhotos(d),false,true)}</div>`:''}<div class="timeline">${d.activities.map(a=>`<section class="activity${a.excluded?' is-excluded':''}"><div class="activity-time"><span>${esc(a.time[0]||'')}</span><strong>${esc(a.time.slice(1).join(' · '))}</strong></div><span class="activity-emoji">${esc(a.emoji)}</span><div class="activity-content"><h2>${placeText(a.title)}</h2>${a.body.filter(n=>!/拍照点/.test(n.name||'')&&!(a.infoCard&&isActivityInfoNode(n))).map(renderNode).join('')}${activityNavigationHTML(a)}${activityInfoHTML(a)}${activityDrivesHTML(a)}${a.body.filter(n=>/拍照点/.test(n.name||'')).map(renderNode).join('')}</div></section>`).join('')}</div>${dailyStayHTML(d)}</article><section class="map-section"><div class="map-heading"><h2 class="section-heading">当日地图</h2><small>${pts.length} 个点位 · 可缩放与展开</small></div>${mapMarkup('day-map',`DAY ${String(d.num).padStart(2,'0')} · 沿途点位`,pts)}</section><nav class="day-pagination">${prev?`<a href="#day/${prev.num}"><small>← 上一天 · DAY ${String(prev.num).padStart(2,'0')}</small>${esc(prev.title)}</a>`:'<span></span>'}${next?`<a href="#day/${next.num}"><small>下一天 · DAY ${String(next.num).padStart(2,'0')} →</small>${esc(next.title)}</a>`:''}</nav></div>`;createMap('day-map',pts,`DAY ${String(d.num).padStart(2,'0')} · 当日地图`,false,null,d.num);}
const budget={"people": 2, "nights": 14, "nightly": 1000, "visa": 1000, "flights": [["上海 → 赫尔辛基", 6141], ["赫尔辛基 → 特罗姆瑟", 2265], ["特罗姆瑟 → 雷克雅未克", 1487], ["雷克雅未克 → 哥本哈根", 1692], ["哥本哈根 → 上海", 4376]], "car": [["挪威租车", "2.7 10:00 – 2.14 10:00 · 7天", 5488], ["冰岛租车", "2.14 15:00 – 2.19 15:00 · 5天", 5213.395], ["油费", "挪威与冰岛全程预估", 4000]], "activities": [["塞尼亚岛｜Hesten／Segla 雪山徒步", 0], ["特罗姆瑟｜峡湾游船与海钓", 1358], ["特罗姆瑟｜驯鹿雪橇25–30分钟", 1534.2], ["特罗姆瑟｜自主越野滑雪 · 雪具租赁", 325.5], ["冰岛｜Jökulsárlón 偏远冰洞＋冰川徒步", 2150.7]], "excluded": [["罗弗敦｜传统渔船冬季海钓", 900], ["冰岛｜Blue Lagoon 蓝湖 · Comfort", 1059.8], ["冰岛｜Katla 冰洞＋超级吉普车", 1616.8], ["特罗姆瑟｜哈士奇雪橇", 2399], ["罗弗敦｜海鹰 RIB 与 Trollfjord", 560], ["特罗姆瑟｜Kvaløya 雪鞋登高徒步", 1054]]};
const money=n=>'¥'+n.toLocaleString('zh-CN',{maximumFractionDigits:0});
function budgetTotals(){const sum=xs=>xs.reduce((a,x)=>a+x.at(-1),0),catalog=experiences.filter(x=>!x.excluded),flights=sum(budget.flights),car=sum(budget.car),activities=sum(budget.activities.filter((x,i)=>!catalog[i]?.budgetAlternative)),alternativeActivities=activities+budget.activities.reduce((delta,x,i)=>{const item=catalog[i];if(!item?.budgetAlternative)return delta;const primary=catalog.find(e=>e.choiceGroup===item.choiceGroup&&!e.budgetAlternative);return delta+x.at(-1)-(primary?.price||0);},0),stay=lodgings.length?lodgings.reduce((sum,s)=>sum+stayBudget(s),0):budget.nights*budget.nightly,base=budget.visa+flights+car/budget.people+stay;return {flights,car,activities,alternativeActivities,stay,base,perPerson:base+activities,alternativePerPerson:base+alternativeActivities,total:(base+activities)*budget.people};}
function ctripSearch(f,people=2){
   // Ctrip's mobile route uses city codes; airport filters are separate parameters.
   const cities={PVG:{code:'SHA',name:'上海'},KEF:{code:'REK',name:'雷克雅未克'},HEL:{code:'HEL',name:'赫尔辛基'},TOS:{code:'TOS',name:'特罗姆瑟'},CPH:{code:'CPH',name:'哥本哈根'}};
   const from=cities[f.origin]||{code:f.origin,name:f.origin},to=cities[f.destination]||{code:f.destination,name:f.destination};
   const params=new URLSearchParams({dcode:from.code,acode:to.code,ddate:f.date,nop:people+'-0-0',seat:'5',dcityName:from.name,acityName:to.name});
   if(f.origin==='PVG')params.set('dfilter','dport:PVG');
   const url=new URL('https://m.ctrip.com/html5/flight/taro/interFirst');url.search=params;return url.href;
}

