function openMap(id){const origin=maps.find(x=>x.id===id);if(!origin)return;lastFocus=document.activeElement;expandedPoints=origin.activePoints||origin.pts;$('#map-modal').hidden=false;$('#map-modal-title').textContent=origin.title;$('#map-list').classList.toggle('closed',innerWidth<=860);$('#points-toggle').setAttribute('aria-expanded',String(innerWidth>860));$('#point-search').value='';document.body.style.overflow='hidden';const expandedMap=createMap('expanded-map',origin.pts,origin.title,true,origin.routeCountry?.id,origin.dayNumber);if(origin.routeVisible){expandedMap.routeDay=origin.routeDay;showCountryRoutes(expandedMap,true);}renderPointList();$('#map-close').focus();}
