document.addEventListener('click',e=>{const project=e.target.closest('a.budget-project,a.flight-monitor-entry');const budgetBack=e.target.closest('a[href="#budget"]');if(!e.defaultPrevented&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&(e.button===0||e.button===undefined)&&(project&&view.type==='budget'||budgetBack&&['stay','experience','car','flights'].includes(view.type))){const href=(project||budgetBack).getAttribute('href');if(project)rememberBudgetPosition(href);e.preventDefault();history.pushState(null,'',href);route();}const exp=e.target.closest('[data-expand]');if(exp)openMap(exp.dataset.expand);const pt=e.target.closest('[data-point]');if(pt){const p=expandedPoints.find(p=>p.id===pt.dataset.point)||points.find(p=>p.id===pt.dataset.point);if(expanded){expanded.map.flyTo([p.coord[1],p.coord[0]],Math.max(expanded.map.getZoom(),12),{duration:.5});}openPoint(p);}if(e.target.closest('[data-close-point]'))closePoint();const st=e.target.closest('[data-side-country]');if(st){setCountry(st.dataset.sideCountry);if(view.type!=='home'){const nextHash=(['restaurants','restaurant'].includes(view.type)?'#restaurants/':['attractions','attraction','country-intro'].includes(view.type)?'#attractions/':'#country/')+st.dataset.sideCountry;keepNavOnRoute=location.hash!==nextHash&&$('#sidebar').classList.contains('open');location.hash=nextHash;}else if(innerWidth>860){scrollCountry(st.dataset.sideCountry);}}const ht=e.target.closest('[data-home-country]');if(ht)scrollCountry(ht.dataset.homeCountry);if(e.target.closest('#sidebar a'))closeNav();});
function scrollCountry(id){setCountry(id);navLock=true;$('#section-'+id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});setTimeout(()=>navLock=false,1000);}
$('#menu-open').onclick=openNav;$('#nav-scrim').onclick=closeNav;$('#map-close').onclick=closeMap;$('#point-scrim').onclick=closePoint;$('#points-toggle').onclick=()=>{$('#map-list').classList.toggle('closed');$('#points-toggle').setAttribute('aria-expanded',String(!$('#map-list').classList.contains('closed')));setTimeout(()=>expanded?.map.invalidateSize(),260);};$('#point-search').oninput=e=>renderPointList(e.target.value);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#point-sheet').hidden)closePoint();else if(!$('#map-modal').hidden)closeMap();else closeNav();}if(e.key==='Tab'){const scope=!$('#point-sheet').hidden?$('#point-sheet'):!$('#map-modal').hidden?$('#map-modal'):$('#sidebar').classList.contains('open')?$('#sidebar'):null;if(scope){const focusable=[...scope.querySelectorAll('a,button,input,[tabindex="0"]')].filter(n=>n.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}});
