const attractionCountryIntro={
 finland:'中央车站 → Oodi → 参议院广场 → Esplanadi；西侧建筑与海岛作为支线。',
 norway:'特罗姆瑟 → 塞尼亚 → Fredvang → Hamnøy／Reine → 北返斯沃尔维尔 → Henningsvær → 特罗姆瑟。',
 iceland:'KEF → 教堂秋千 → Hveragerði → 黄金圈 → 南岸双瀑布 → 维克 → 冰川区 → 霍芬／Stokksnes → 西返凯夫拉维克。',
 denmark:'新港 → 皇宫区 → FRAMA；次日设计博物馆 → 市中心购物 → 黑钻图书馆。'
};
const countryIntroductions={
 finland:{hero:'helsinki-cathedral',tagline:'森林、桑拿与融入日常的设计',lead:'从赫尔辛基出发，看芬兰怎样把自然、公共生活与设计连接起来。',sections:[
  ['城市里的自然感','芬兰的森林与桑拿文化，为理解这个国家提供了很好的入口。木材、温暖的室内和户外环境之间的联系，也会延伸到城市建筑与生活用品中。在赫尔辛基，不妨把目光放在公共图书馆、街道和商店，观察设计怎样服务普通人的一天。'],
  ['不同年代的城市表情','参议院广场与白色大教堂呈现新古典主义的首都形象；1919年启用的中央车站，则连接着独立后城市发展的历史。岩石教堂把建筑带入天然基岩，Oodi 又把图书馆扩展为可阅读、创作与交流的公共客厅。几种建筑放在一起，便能看出城市空间如何不断变化。'],
  ['这次怎么感受芬兰','本次主要停留在赫尔辛基，以市中心建筑、芬兰设计和街区散步为主。抵达日下午适合挑少量重点慢看：在建筑里体会光线与材料，再沿 Esplanadi 看橱窗与街道。不必用一天代表整个芬兰，把这一站当作认识北欧城市生活的开场就很好。']
 ],sources:['https://oodihelsinki.fi/en/what-is-oodi/architecture/','https://paarautatieasema.fi/en/info/history','https://media.visitfinland.com/en/media-press-releases/finnish-sauna-culture-new-experiences-finland/']},
 norway:{hero:'ersfjordbotn',tagline:'峡湾、渔村与北方海岸生活',lead:'这次走进的是挪威北部：特罗姆瑟、塞尼亚和罗弗敦，一段沿山海展开的冬季旅程。',sections:[
  ['山海塑造的聚落','理解北挪威，可以先看房屋和道路落在哪里。陡峭山体与曲折海岸之间的平地有限，村落、码头和交通便沿着海湾展开。桥梁、隧道与渡海联系让分散的社区彼此连接，也使一段自驾行程不断在山、海和居民生活之间切换。'],
  ['渔业与极地故事','罗弗敦的渔屋、鱼架和港口背后，是长期的季节性鳕鱼捕捞与鱼干贸易。它们不仅构成风景，也曾组织起工作、居住和交易。特罗姆瑟的极地博物馆则带出捕猎与探险历史；体验萨米文化时，也应把它理解为仍在延续的生活与文化，而不是只属于过去的故事。'],
  ['这次怎么感受挪威','从特罗姆瑟的城市与峡湾出发，再到塞尼亚的陡峭山海，随后进入罗弗敦的渔村和海滩。除了远山与极光，也值得留意码头、船只、屋里的灯光和小店。二月的雪与短暂日光会改变沿途气氛，适合为真正喜欢的一两处景观留出停留时间。']
 ],sources:['https://www.visitnorway.com/places-to-go/northern-norway/the-lofoten-islands/','https://www.visittromso.no/learn-about-history-tromso','https://www.visitnorway.no/om-norge/historie-og-tradisjoner/']},
 iceland:{hero:'jokulsarlon',tagline:'火山、冰川与地热中的人文线索',lead:'沿南岸向东，再折返西行，在不断变化的地表中读冰岛的自然与生活。',sections:[
  ['仍在变化的土地','冰岛的火山、冰川与地热并不是彼此分离的景观。冰舌伸入山谷，融水进入湖泊与海洋；黑沙、玄武岩和蒸汽，则从不同角度展示地表与地下的联系。把冰河湖和钻石沙滩一起看，或把温泉与周边熔岩放在一起理解，会比只记住景点名称更有意思。'],
  ['历史与土地相遇','Þingvellir 不仅呈现裂谷地形，也是约930年建立 Alþingi 议会的历史场所。草皮教堂与农庄建筑让人看到当地材料如何被用于生活，瀑布和海上岩柱的民间传说，则展现人们如何为自然赋予故事。地质成因、历史记录与传说各有意义，值得分开来读。'],
  ['这次怎么感受冰岛','行程以黄金圈与南岸为主，逐步进入瀑布、黑沙滩、冰川和冰河湖，再从霍芬一带西返。这里适合留意景观之间的连续关系：不只拍一座瀑布，也看看它落下的崖壁和远处平原；不只找蓝冰，也观察冰体、水流与山谷怎样相接。']
 ],sources:['https://www.south.is/en/destinations/travel-routes/the-golden-circle','https://www.south.is/en/destinations/travel-routes/the-south-coast','https://whc.unesco.org/fr/listesindicatives/5589']},
 denmark:{hero:'nyhavn',tagline:'港口旧城、王室历史与日常设计',lead:'以哥本哈根为落点，在步行尺度里看历史街区、当代建筑与丹麦设计。',sections:[
  ['一座可以慢走的港城','哥本哈根的运河、广场与街道彼此连接，步行和骑行都是理解城市的好方式。新港今天以彩色立面闻名，过去却是忙碌的商业港口。把老房子、船只、桥和临水空间放在一起看，便能从漂亮街景背后读出城市与海上贸易的关系。'],
  ['从宫殿到公共文化','阿美琳堡、腓特列教堂与罗森堡分别呈现王室居住、城市规划和宫廷生活的线索。丹麦设计博物馆把旧医院转作文化空间，黑钻图书馆则以新建筑连接旧馆与海港。它们让历史建筑与当代设计出现在同一段散步中，而不是被分成互不相干的两种体验。'],
  ['这次怎么感受丹麦','本次以哥本哈根市中心为主，可以沿新港与宫殿区走到 FRAMA，再把设计商店、圆塔和水岸建筑串起来。比起只记住品牌与建筑师，留意椅子的比例、木材与金属的触感、橱窗和街道的关系，更容易体会设计如何进入日常生活。']
 ],sources:['https://www.visitdenmark.com/denmark/things-do/design-art-architecture','https://denmark.dk/people-and-culture/biking/','https://www.kongehuset.dk/en/palaces-and-the-royal-yacht/amalienborg/']}
};
function countryIntroPhoto(c,data){const info=countryIntroductions[c.id];return data.items.find(a=>a.id===info.hero)?.photos[0];}
function countryIntroCardHTML(c,data){const info=countryIntroductions[c.id],photo=countryIntroPhoto(c,data);return `<a class="attractions-country-card" href="#country-intro/${c.id}" aria-label="查看${esc(c.name)}国家介绍">${photo?`<img src="${esc(photo.thumbnail||photo.thumb||photoSrc(photo.src,480))}" alt="" width="90" height="68" loading="lazy">`:''}<div><strong>${esc(c.name)} · 国家介绍</strong><p>${esc(info.tagline)}</p></div><span aria-hidden="true">↗</span></a>`;}
async function renderCountryIntro(c){
 const expectedHash=location.hash,info=countryIntroductions[c.id];document.title=c.name+' · 国家介绍 — 北欧旅行计划';
 $('#main').innerHTML='<div class="page-wrap"><p class="attraction-loading" role="status">正在展开国家介绍…</p></div>';
 try{const data=await loadAttractions();if(location.hash!==expectedHash)return;const photo=countryIntroPhoto(c,data);
 $('#main').innerHTML=`<div class="page-wrap country-intro-page" style="--theme:${c.color}"><nav class="attraction-breadcrumb"><a href="#attractions/${c.id}">← ${esc(c.name)} · 经典景点</a></nav><article class="country-intro-article">${photo?`<img class="country-intro-photo" src="${esc(photoSrc(photo.src,960))}" alt="${esc(photo.label)}" width="960" height="540" fetchpriority="high">`:''}<div class="country-intro-body"><header><p class="country-intro-en">${esc(c.en)}</p><h1>${esc(c.name)}</h1><p class="country-intro-lead">${esc(info.lead)}</p></header>${info.sections.map(([title,text])=>`<section><h2>${esc(title)}</h2><p>${esc(text)}</p></section>`).join('')}<nav class="country-intro-links"><a href="#attractions/${c.id}">浏览经典景点 ↗</a><a href="#country/${c.id}">查看路线地图 ↗</a></nav></div></article></div>`;
 }catch(error){if(location.hash===expectedHash)$('#main').innerHTML=`<div class="page-wrap"><div class="attraction-error"><h1>国家介绍暂时无法加载</h1><a href="#attractions/${c.id}">返回经典景点</a></div></div>`;}
}
function attractionStage(a){
 if(a.country==='finland')return '赫尔辛基 · 抵达日下午与周边候选';
 if(a.country==='norway'){
  if(['ersfjordbotn','sommaroy','fjellheisen','arctic-cathedral','skansen','polar-museum','charlottenlund','pust'].includes(a.id))return '01 · 特罗姆瑟｜D2–D4';
  if(['hesten-segla','mefjordvaer','ersfjordstranda','tungeneset','bergsbotn'].includes(a.id))return '02 · 塞尼亚｜D5–D6';
  if(['henningsvaer','kabelvag','svolvaer'].includes(a.id))return '04 · 罗弗敦北部与返程｜D7–D8';
  return '03 · 罗弗敦南部与北返｜D7';
 }
 if(a.country==='iceland'){
  if(a.id==='hallgrimskirkja')return '01 · 雷市教堂 → Hveragerði｜D9';
  if(a.id==='reykjadalur')return '01 · Hveragerði 住宿周边｜D9';
  if(['thingvellir','geysir','gullfoss'].includes(a.id))return '02 · 黄金圈东行 → 南岸｜D10';
  if(['seljalandsfoss','gljufrabui','skogafoss','kvernufoss','solheimajokull','dyrholaey','vik-church'].includes(a.id))return '02 · 南岸瀑布 → 维克｜D10';
  if(['reynisfjara','fjadrargljufur','stjornarfoss'].includes(a.id))return '03 · 维克 → 霍芬｜D11';
  if(['hofskirkja','skaftafell-ice','fjallsarlon','jokulsarlon','diamond-beach'].includes(a.id))return '04 · 冰川区与冰河湖｜D12';
  if(a.id==='vestrahorn')return '05 · Stokksnes → 西返｜D13';
  return '06 · 额外支线｜需要替换现有行程';
 }
 if(['nyhavn','amalienborg','frederiks-church','frama'].includes(a.id))return '01 · 新港 → 皇宫区 → FRAMA｜D14';
 if(a.id==='louisiana')return '03 · 北郊支线｜需要替换半天';
 return '02 · 设计 → 市中心 → 河岸｜D15';
}
function attractionRating(a){return a.score>=9?'强烈推荐':a.score>=8?'值得去':'有余裕再去';}
function attractionScoreHTML(a){const tier=a.score>=9?'high':a.score>=8?'mid':'low';return `<span class="attraction-score attraction-score-${tier}" aria-label="推荐分 ${a.score.toFixed(1)} / 10，${attractionRating(a)}"><strong>${a.score.toFixed(1)}</strong><small>/ 10</small></span>`;}
function attractionBadge(a){return a.days.length?`<span class="attraction-included">D${a.days.join(' / D')}</span>`:'<span class="attraction-optional">未包含</span>';}
async function loadAttractions(){
 if(attractionData)return attractionData;
 if(!attractionRequest)attractionRequest=fetch('../nordic-v2/attractions.json?v=9').then(r=>{if(!r.ok)throw Error('attractions');return r.json();}).then(data=>attractionData=data).catch(error=>{attractionRequest=null;throw error;});
 return attractionRequest;
}
async function renderAttractions(countryId,attractionId){
 const c=countryById(countryId),expectedHash=location.hash;
 $('#main').innerHTML='<div class="page-wrap"><p class="attraction-loading" role="status">正在整理景点…</p></div>';
 try{
  const data=await loadAttractions();if(location.hash!==expectedHash)return;
  if(attractionId){const a=data.items.find(x=>x.id===attractionId);if(!a){renderAttractionMissing(c);return;}renderAttractionDetail(a,data);return;}
  const items=data.items.filter(x=>x.country===c.id);let previousStage='';document.title=c.name+' · 经典景点 — 北欧旅行计划 V2';
  $('#main').innerHTML=`<div class="page-wrap attractions-page" style="--theme:${c.color}">
   <header class="attractions-heading"><h1>经典景点</h1><a class="attractions-route-link" href="#country/${c.id}">路线地图 ↗</a></header><p class="attractions-eyebrow attractions-count">${esc(c.name)} · ${items.length} 个景点</p>
   <p class="attractions-intro">${esc(attractionCountryIntro[c.id])}</p>
   ${countryIntroCardHTML(c,data)}
   <div class="attractions-sticky-bar"><nav class="attractions-countries" aria-label="选择国家景点">${countries.map(x=>`<a href="#attractions/${x.id}" ${x.id===c.id?'aria-current="page"':''}>${esc(x.name)}</a>`).join('')}</nav><span class="attractions-current-stage" title="${esc(attractionStage(items[0]))}">${esc(attractionStage(items[0]))}</span></div>
   <div class="attractions-list">${items.map((a,i)=>{const stage=attractionStage(a),heading=stage!==previousStage?`<h2 class="attraction-stage">${esc(stage)}</h2>`:'';previousStage=stage;return `${heading}<a class="attraction-row" href="#attraction/${a.id}"><div class="attraction-row-title"><h3><span class="attraction-title-number">${String(i+1).padStart(2,'0')}</span> ${esc(a.name)}</h3>${attractionScoreHTML(a)}</div><div class="attraction-row-bottom"><img class="attraction-thumbnail" src="${esc(a.photos[0]?.thumbnail||a.photos[0]?.thumb||photoSrc(a.photos[0]?.src||'',480))}" style="object-position:${esc(a.photos[0]?.position||'50% 50%')}" alt="" width="104" height="88" loading="${i<2?'eager':'lazy'}" decoding="async"><div class="attraction-row-content"><p>${esc(a.summary)}</p><div class="attraction-row-meta">${attractionBadge(a)}<span>${esc(a.duration)}</span></div></div></div></a>`;}).join('')}</div><details class="attraction-photo-credits"><summary>图片来源</summary>${items.flatMap(a=>a.photos.filter(p=>p.credit).map(p=>`<p><a href="${esc(p.credit.url)}" target="_blank" rel="noopener noreferrer">${esc(p.label)} · ${esc(p.credit.author)} · ${esc(p.credit.license)} ↗</a></p>`)).join('')}<p>图片经过缩放；列表缩略图可能裁切。其余图片沿用现有行程图库。</p></details>
  </div>`;
  requestAnimationFrame(updateAttractionStickyStage);
  if(attractionListReturn?.hash===expectedHash){const saved=attractionListReturn;requestAnimationFrame(()=>{if(location.hash===expectedHash)window.scrollTo({top:saved.y,behavior:'instant'});});}
 }catch(error){if(location.hash===expectedHash)$('#main').innerHTML=`<div class="page-wrap"><div class="attraction-error"><h1>景点暂时无法加载</h1><p>请检查网络后重试。</p><a href="#country/${c.id}">返回路线</a><button type="button" data-retry-attractions>重试</button></div></div>`;}
}
function updateAttractionStickyStage(){
 const bar=$('.attractions-sticky-bar');if(!bar)return;
 const label=bar.querySelector('.attractions-current-stage'),stages=$$('.attractions-list>.attraction-stage');
 const edge=bar.getBoundingClientRect().bottom+12;let current=stages[0];
 for(const stage of stages){if(stage.getBoundingClientRect().top<=edge)current=stage;else break;}
 if(current&&label.textContent!==current.textContent){label.textContent=current.textContent;label.title=current.textContent;}
}
let attractionScrollFrame=0;
function scheduleAttractionStickyStage(){if(attractionScrollFrame||!$('.attractions-sticky-bar'))return;attractionScrollFrame=requestAnimationFrame(()=>{attractionScrollFrame=0;updateAttractionStickyStage();});}
window.addEventListener('scroll',scheduleAttractionStickyStage,{passive:true});
window.addEventListener('resize',scheduleAttractionStickyStage);
function renderAttractionMissing(c){$('#main').innerHTML=`<div class="page-wrap"><div class="attraction-error"><h1>未找到这个景点</h1><a href="#attractions/${c.id}">返回景点列表</a></div></div>`;}
function attractionGalleryHTML(a){
 if(!a.photos.length)return '';
 const multiple=a.photos.length>1;
 return `<div class="attraction-gallery" data-attraction="${esc(a.id)}" data-photo-index="0"><div class="attraction-gallery-stage"><div class="attraction-track" tabindex="0" role="region" aria-label="${esc(a.name)}图片，左右滑动查看">${a.photos.map((p,i)=>`<figure class="attraction-hero"><img src="${esc(photoSrc(p.src,960))}" alt="${esc(p.label)}" style="object-position:${esc(p.position||'50% 50%')}" width="960" height="540" loading="${i===0?'eager':'lazy'}" decoding="async" fetchpriority="${i===0?'high':'auto'}"></figure>`).join('')}</div>${multiple?`<button class="gallery-arrow gallery-prev" data-attraction-step="-1" aria-label="上一张图片"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><button class="gallery-arrow gallery-next" data-attraction-step="1" aria-label="下一张图片"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button><span class="gallery-count" aria-live="polite">1 / ${a.photos.length}</span>`:''}</div>${multiple?`<div class="experience-thumbnails attraction-thumbnails" aria-label="选择图片">${a.photos.map((p,i)=>`<button data-attraction-photo="${i}" aria-label="查看图片${i+1}：${esc(p.label)}" aria-pressed="${i===0}"><img src="${esc(p.thumbnail||p.thumb||photoSrc(p.src,480))}" alt="" loading="lazy" decoding="async"></button>`).join('')}</div>`:''}</div>`;
}
function selectAttractionPhoto(index){
 const gallery=$('.attraction-gallery');if(!gallery)return;
 const track=gallery.querySelector('.attraction-track'),count=track.children.length,next=(index%count+count)%count;
 track.scrollTo({left:next*track.clientWidth,behavior:'instant'});
 gallery.dataset.photoIndex=String(next);const counter=gallery.querySelector('.gallery-count');if(counter)counter.textContent=`${next+1} / ${count}`;gallery.querySelectorAll('[data-attraction-photo]').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===next)));
}
document.addEventListener('click',event=>{const thumb=event.target.closest('[data-attraction-photo]'),arrow=event.target.closest('[data-attraction-step]');if(thumb)selectAttractionPhoto(Number(thumb.dataset.attractionPhoto));if(arrow)selectAttractionPhoto(Number(arrow.closest('.attraction-gallery').dataset.photoIndex)+Number(arrow.dataset.attractionStep));});
document.addEventListener('keydown',event=>{if(event.target.closest?.('.attraction-gallery')&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();selectAttractionPhoto(Number($('.attraction-gallery').dataset.photoIndex)+(event.key==='ArrowRight'?1:-1));}});
document.addEventListener('scroll',event=>{const track=event.target;if(!track.matches?.('.attraction-track'))return;const gallery=track.closest('.attraction-gallery'),index=Math.max(0,Math.min(track.children.length-1,Math.round(track.scrollLeft/track.clientWidth)));gallery.dataset.photoIndex=String(index);const counter=gallery.querySelector('.gallery-count');if(counter)counter.textContent=`${index+1} / ${track.children.length}`;gallery.querySelectorAll('[data-attraction-photo]').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));},true);
function renderAttractionDetail(a,data){
 const c=countryById(a.country),siblings=data.items.filter(x=>x.country===a.country),index=siblings.indexOf(a),prev=siblings[index-1],next=siblings[index+1];
 currentCountry=a.country;sideRender();document.title=a.name+' — 北欧经典景点';
 $('#main').innerHTML=`<div class="page-wrap attraction-detail-page" style="--theme:${c.color}">
  <nav class="attraction-breadcrumb"><a href="#attractions/${c.id}" aria-label="返回${esc(c.name)}景点列表">← ${esc(c.name)} · 经典景点</a></nav>
  <article class="attraction-detail">
   ${attractionGalleryHTML(a)}
   <div class="attraction-detail-body"><header class="attraction-detail-title"><h1>${esc(a.name)}</h1>${attractionScoreHTML(a)}</header>
    <div class="attraction-detail-meta">${attractionBadge(a)}<span>建议 ${esc(a.duration)}</span></div>
    <p class="attraction-lead">${esc(a.summary)}</p>
    ${a.openingHours?`<section class="attraction-opening${a.openingHours.status==='closed-during-trip'?' is-closed':''}" aria-label="开放时间"><h2>开放时间</h2>${a.openingHours.lines.map(line=>`<p>${esc(line)}</p>`).join('')}<p class="opening-note">${esc(a.openingHours.note)}</p><div class="opening-source"><span>当地时间 · 核实于 ${esc(a.openingHours.checkedAt)}</span><a href="${esc(a.openingHours.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看官方开放安排 ↗</a></div></section>`:''}
    ${a.description?.length?`<div class="attraction-story">${a.description.map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}</div>`:''}
    <section class="attraction-plan"><h2>怎么顺路去</h2><p>${esc(a.route)}</p><a class="attraction-map-link" href="${mapsURL(a.query)}" target="_blank" rel="noopener noreferrer">${esc(a.name)} · Google Maps ↗</a></section>
    ${a.days.length?`<div class="attraction-day-links"><span>在每日行程中查看</span>${a.days.map(n=>`<a href="#day/${n}">DAY ${String(n).padStart(2,'0')} ↗</a>`).join('')}</div>`:'<p class="attraction-not-scheduled">未包含在当前每日行程中，可按上面的建议替换或调整。</p>'}
   </div>
  </article>
  <nav class="attraction-neighbours" aria-label="按路线浏览景点">${prev?`<a href="#attraction/${prev.id}"><small>上一站</small><span>← ${esc(prev.name)}</span></a>`:'<span></span>'}${next?`<a href="#attraction/${next.id}"><small>下一站</small><span>${esc(next.name)} →</span></a>`:'<span></span>'}</nav>
 </div>`;
}
document.addEventListener('click',e=>{const a=e.target.closest('a.attraction-row,a.attractions-country-card');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&(e.button===0||e.button===undefined))attractionListReturn={hash:location.hash,y:window.scrollY};if(e.target.closest('[data-retry-attractions]'))renderAttractions(currentCountry,view.type==='attraction'?view.id:null);});


// Dining recommendations share the route-ordered attraction layout and swipe gallery.
let diningData=null,diningRequest=null,diningListReturn=null;
function diningTopRank(a){const x=a.xiaohongshu;return x?.recommended&&x.rankingSource==='user-supplied-diandian-screenshot'&&Number.isInteger(x.rank)&&x.rank>=1&&x.rank<=6?x.rank:null;}
function diningPriceText(a){const p=a.averagePrice;if(!p)return '';const n=v=>v.toLocaleString('en-US',{minimumFractionDigits:Number.isInteger(v)?0:2,maximumFractionDigits:2});const range=p.min===1?'≤'+n(p.max):p.min===p.max?n(p.min):n(p.min)+'–'+n(p.max);return p.currency==='EUR'?'€'+range:range+' '+p.currency;}
function diningTags(a){const rank=diningTopRank(a);return `<span class="attraction-included">${esc(dayRanges(a.days))}</span><span>${esc(a.kind)}</span>${a.visitOnly?'<span class="dining-visit-only">仅参观</span>':''}${(a.viewTags||[]).map(t=>`<span class="dining-view-tag">${esc(t)}</span>`).join('')}${a.hours?.status==='closed-during-trip'?'<span class="dining-closed">二月停业</span>':a.hours?.needsConfirmation?'<span class="dining-seasonal">冬季营业待确认</span>':''}${rank?`<span class="dining-rednote">小红书推荐Top${rank}</span>`:a.xiaohongshu?.recommended&&a.xiaohongshu.evidence?.length>=2?'<span class="dining-rednote">小红书推荐</span>':''}`;}
function diningRating(a,linked=false){const text=`<strong>${a.google.rating.toFixed(1)}<small> / 5</small></strong><span>${a.google.reviewCount.toLocaleString('zh-CN')} 条评论</span>`;return linked?`<a class="dining-rating" href="${esc(a.google.url)}" target="_blank" rel="noopener noreferrer" aria-label="Google Maps ${a.google.rating}分，${a.google.reviewCount}条评论">${text}</a>`:`<span class="dining-rating" aria-label="Google Maps ${a.google.rating}分，${a.google.reviewCount}条评论">${text}</span>`;}
async function renderDining(countryId,itemId){
 const expectedHash=location.hash;
 $('#main').innerHTML='<div class="page-wrap"><p role="status">正在整理餐厅与酒吧…</p></div>';
 try{
  if(!diningData){if(!diningRequest)diningRequest=fetch('../nordic-v2/dining.json?v=8').then(r=>{if(!r.ok)throw Error('dining');return r.json();}).then(x=>diningData=x).catch(e=>{diningRequest=null;throw e;});await diningRequest;}
  if(location.hash!==expectedHash)return;
  const item=itemId?diningData.items.find(a=>a.id===itemId):null;
  if(itemId&&!item){$('#main').innerHTML='<div class="page-wrap"><h1>未找到这家店</h1><a href="#restaurants/'+currentCountry+'">返回餐厅列表</a></div>';return;}
  const c=countryById(item?.country||countryId),items=diningData.items.filter(a=>a.country===c.id);currentCountry=c.id;sideRender();
  if(item){renderDiningDetail(item,c,items);return;}
  document.title=c.name+' · 餐厅／酒吧 — 北欧旅行计划';let stage='';
  $('#main').innerHTML=`<div class="page-wrap attractions-page dining-page" style="--theme:${c.color}"><header class="attractions-heading"><h1>餐厅／酒吧</h1></header><p class="attractions-eyebrow attractions-count">${esc(c.name)} · ${items.length} 家 · 沿每日路线排列</p><p class="dining-intro">每顿选一家，按当天路线与营业时间取舍。</p><p class="dining-visit-legend">“仅参观”以外观打卡为主，不安排正式用餐；入座消费、门票与桑拿按店方规则。</p><div class="attractions-sticky-bar"><nav class="attractions-countries" aria-label="选择国家餐厅">${countries.map(x=>`<a href="#restaurants/${x.id}" ${x.id===c.id?'aria-current="page"':''}>${esc(x.name)}</a>`).join('')}</nav><span class="attractions-current-stage">${esc(items[0]?.stage||'')}</span></div><div class="attractions-list">${items.map((a,i)=>{const heading=stage!==a.stage?`<h2 class="attraction-stage">${esc(a.stage)}</h2>`:'';stage=a.stage;return `${heading}<a class="attraction-row dining-row" href="#restaurant/${a.id}"><div class="attraction-row-title"><h3><span class="attraction-title-number">${String(i+1).padStart(2,'0')}</span> ${esc(a.name)}</h3>${diningRating(a)}</div><div class="attraction-row-bottom"><img class="attraction-thumbnail" src="${esc(a.photos[0].thumbnail)}" alt="${esc(a.name)}店铺实景" width="104" height="88" loading="${i<2?'eager':'lazy'}" decoding="async"><div class="attraction-row-content"><p>${esc(a.summary)}</p><p class="dining-row-price">人均 ${esc(diningPriceText(a))}</p><div class="attraction-row-meta">${diningTags(a)}<span>${esc(a.meal)}</span></div></div></div></a>`;}).join('')}</div><p class="dining-data-date">评分与评论数来自 Google Maps · 核对于 ${esc(diningData.updatedAt)}</p></div>`;
  requestAnimationFrame(()=>{updateAttractionStickyStage();if(diningListReturn?.hash===expectedHash&&location.hash===expectedHash)window.scrollTo({top:diningListReturn.y,behavior:'instant'});});
 }catch(error){if(location.hash===expectedHash)$('#main').innerHTML='<div class="page-wrap attraction-error"><h1>餐厅暂时无法加载</h1><p>请检查网络后重试。</p><button type="button" data-retry-dining>重试</button></div>';}
}
function renderDiningDetail(a,c,items){
 document.title=a.name+' · 餐厅／酒吧 — 北欧旅行计划';const index=items.indexOf(a),prev=items[index-1],next=items[index+1];
 $('#main').innerHTML=`<div class="page-wrap attraction-detail-page dining-detail-page" style="--theme:${c.color}"><nav class="attraction-breadcrumb"><a href="#restaurants/${c.id}">← ${esc(c.name)} · 餐厅／酒吧</a></nav><article class="attraction-detail">${attractionGalleryHTML(a)}<div class="attraction-detail-body"><header class="attraction-detail-title"><h1>${esc(a.name)}</h1>${diningRating(a,true)}</header><div class="attraction-detail-meta dining-meta">${diningTags(a)}</div><p class="dining-google-note">Google Maps · ${esc(a.google.checkedAt.slice(0,10))}${a.google.note?' · '+esc(a.google.note):''}</p>${a.visitOnly?`<p class="dining-visit-note"><span>仅参观</span>${esc(a.visitNote)}</p>`:''}<div class="dining-price-detail"><strong>人均 ${esc(diningPriceText(a))}</strong><p>${esc(a.averagePrice.note)}</p><a href="${esc(a.averagePrice.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(a.averagePrice.basis)} ↗</a></div><p class="attraction-lead">${esc(a.summary)}</p><div class="attraction-story">${a.description.map(p=>`<p>${esc(p)}</p>`).join('')}</div><section class="dining-menu"><header><h2>菜单与特色</h2><a href="${esc(a.google.url)}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a></header>${a.menu.dishes?.length?`<div class="dining-dish-grid">${a.menu.dishes.map(d=>`<figure class="dining-dish"><a href="${esc(a.google.url)}" target="_blank" rel="noopener noreferrer" aria-label="在Google Maps查看${esc(d.name)}"><img src="${esc(d.photo)}" alt="${esc(d.name)} · 本店实拍" width="320" height="240" loading="lazy" decoding="async"></a><figcaption><div><strong>${esc(d.name)}</strong><span>${esc(d.price)}</span></div><p>${esc(d.description)}</p></figcaption></figure>`).join('')}</div>${a.menu.dishesWithoutPhoto?.length?`<ul class="dining-more-dishes">${a.menu.dishesWithoutPhoto.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`:`<ul>${a.menu.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}<p class="dining-fine">${esc(a.menu.note)}</p></section><section class="attraction-opening"><h2>营业时间</h2>${a.hours.lines.map(x=>`<p>${esc(x)}</p>`).join('')}</section><section class="attraction-plan dining-address"><h2>地址</h2><a class="attraction-map-link" href="${esc(a.google.url)}" target="_blank" rel="noopener noreferrer">${esc(a.address)} ↗</a></section>${a.xiaohongshu?.recommended?`<details class="dining-evidence"><summary>小红书推荐依据</summary><p>${esc(a.xiaohongshu.note||'已核对多篇独立到店笔记；热门不代表每个人都适合。')}</p><p>原帖可能需在小红书 App 打开；也可 <a href="https://www.xiaohongshu.com/search_result?keyword=${encodeURIComponent(a.name)}" target="_blank" rel="noopener noreferrer">搜索店名 ↗</a></p>${a.xiaohongshu.evidence.map(x=>`<p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></p>`).join('')}</details>`:''}<details class="dining-evidence"><summary>图片与资料来源</summary>${a.sources.map(x=>x.url?`<p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></p>`:`<p>${esc(x.title)}</p>`).join('')}<p>${a.photos.some(p=>p.userProvided)?'实景照片来自本店Google Maps图片及用户提供的小红书截图':'实景照片来自本店Google Maps图片'}，权利归店方与原作者；照片可能裁切。</p></details></div></article><nav class="attraction-neighbours" aria-label="沿路线浏览餐厅">${prev?`<a href="#restaurant/${prev.id}"><small>上一家</small><span>← ${esc(prev.name)}</span></a>`:'<span></span>'}${next?`<a href="#restaurant/${next.id}"><small>下一家</small><span>${esc(next.name)} →</span></a>`:'<span></span>'}</nav></div>`;
}
